<?php use App\Models\EquipmentModel; use Livewire\Attributes\Title; use Livewire\Component; use Livewire\WithPagination; new #[Title('Models')] class extends Component { use WithPagination; public string $search=''; public function updatedSearch():void{$this->resetPage();} public function with():array{return['models'=>EquipmentModel::with('make')->when($this->search,fn($q)=>$q->where('name','like','%'.$this->search.'%')->orWhereHas('make',fn($q)=>$q->where('name','like','%'.$this->search.'%')))->orderBy('name')->paginate(20)];}}; ?>
<section class="w-full p-6"><div class="mb-4 flex justify-between"><flux:heading size="xl">Equipment models</flux:heading>@can('setup.model.create')<flux:button variant="primary" :href="route('setup.models.create')">Add model</flux:button>@endcan</div><flux:input class="mb-4" wire:model.live.debounce.300ms="search" placeholder="Search makes and models"/><flux:table :paginate="$models"><flux:table.columns><flux:table.column>Make</flux:table.column><flux:table.column>Model</flux:table.column></flux:table.columns><flux:table.rows>@foreach($models as $model)<flux:table.row :key="$model->id"><flux:table.cell>{{$model->make?->name}}</flux:table.cell><flux:table.cell>{{$model->name}}</flux:table.cell></flux:table.row>@endforeach</flux:table.rows></flux:table></section>
